/**
 * Builds src/data/tokenization.ts from the verified research payload.
 *
 * The source file is generated by the actual Qwen2.5 tokenizer (tokenizers==0.23.3)
 * and independently re-checked by research/verify_example_json.py. Never hand-edit
 * token ids or token text in the generated file; re-run this script instead.
 *
 *   node scripts/build-tokenizer-data.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = path.join(root, 'research', 'tokenizer-example.json');
const target = path.join(root, 'src', 'data', 'tokenization.ts');

const raw = JSON.parse(fs.readFileSync(source, 'utf8'));
if (!raw.question?.concatenated_ok || !raw.answer?.concatenated_ok) {
  throw new Error('Tokenizer research payload failed its decode validation.');
}

const cleanToken = (token) => ({
  index: token.index,
  id: token.id,
  display: token.display,
  raw: token.raw,
  offsetStart: token.offset_start,
  offsetEnd: token.offset_end,
  byteLen: token.byte_len,
  kind: token.kind,
});

const question = raw.question.tokens.map(cleanToken);
const answer = raw.answer.tokens.map(cleanToken);
const chunks = raw.answer_chunks.map((chunk) => ({
  index: chunk.chunk_index,
  tokenStart: chunk.token_start,
  tokenEnd: chunk.token_end,
  text: chunk.text,
  displays: chunk.displays,
}));

const payload = {
  citation: {
    tokenizer: raw.tokenizer.name,
    repo: raw.tokenizer.repo,
    file: raw.tokenizer.file,
    revision: raw.tokenizer.revision_or_hash.hf_repo_commit,
    localSha256: raw.tokenizer.revision_or_hash.local_sha256,
    library: raw.tokenizer.library,
    sourceUrl: raw.tokenizer.source_url,
    verified: 'decode(ids) === source text；offsets 与词表逐项复核通过',
  },
  question: {
    text: raw.question.text,
    tokens: question,
  },
  answer: {
    text: raw.answer.text,
    tokens: answer,
  },
  chunks,
  newlineVariant: {
    text: raw.question_with_newline.text,
    tokens: raw.question_with_newline.tokens.map(cleanToken),
  },
  specialTokens: {
    bos: raw.special_tokens.bos_token,
    eos: raw.special_tokens.eos_token,
    eosId: raw.special_tokens.eos_id,
    note: 'Qwen2.5 原始文本编码不会自动添加 BOS；聊天模板会加入特殊 token，本可视化只展示内容 token。',
  },
  comparison: {
    tokenizer: raw.cross_check_o200k_base?.encoding ?? 'o200k_base',
    questionCount: raw.cross_check_o200k_base?.question?.n_tokens ?? null,
    answerCount: raw.cross_check_o200k_base?.answer?.n_tokens ?? null,
    note: '同一句中文在不同 tokenizer 中会得到不同的 token 边界与 ID。',
  },
};

const body = `/**
 * AUTO-GENERATED by scripts/build-tokenizer-data.mjs — do not hand-edit.
 * Source: ${payload.citation.repo}/${payload.citation.file}
 * Revision: ${payload.citation.revision}
 * Verified with: ${payload.citation.library}
 */
export interface TokenDatum {
  index: number;
  id: number;
  display: string;
  raw: string;
  offsetStart: number;
  offsetEnd: number;
  byteLen: number;
  kind: string;
}

export interface AnswerChunk {
  index: number;
  tokenStart: number;
  tokenEnd: number;
  text: string;
  displays: readonly string[];
}

export const TOKENIZER_DATA = ${JSON.stringify(payload, null, 2)} as const;

export const QUESTION_TOKENS: readonly TokenDatum[] = TOKENIZER_DATA.question.tokens;
export const ANSWER_TOKENS: readonly TokenDatum[] = TOKENIZER_DATA.answer.tokens;
export const ANSWER_CHUNKS: readonly AnswerChunk[] = TOKENIZER_DATA.chunks;

export const QUESTION_TEXT = TOKENIZER_DATA.question.text;
export const ANSWER_TEXT = TOKENIZER_DATA.answer.text;
export const INPUT_TOKEN_COUNT = QUESTION_TOKENS.length;
export const OUTPUT_TOKEN_COUNT = ANSWER_TOKENS.length;
`;

fs.writeFileSync(target, body);
console.log(`[tokenizer] wrote ${path.relative(root, target)} (${question.length} question tokens, ${answer.length} answer tokens)`);
